{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { normalizeDueDate } from './due-date.js';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec('CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
db.exec(`PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
const projectQuery = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectQuery} ORDER BY p.id ASC`);
const findProject = db.prepare(`${projectQuery} WHERE p.id = ?`);
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const listTasks = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY id ASC');
const findTask = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const taskJSON = task => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/task-filters.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/task-filters.js', import.meta.url))]],
  ['/due-date.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./due-date.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJSON(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

const server = http.createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') return json(response, 200, { status: 'ok' });
    if (request.method === 'GET' && pathname === '/api/projects') return json(response, 200, listProjects.all());
    const projectMatch = pathname.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = findProject.get(projectMatch[1]);
      return json(response, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (request.method === 'POST' && pathname === '/api/projects') {
      const input = await readJSON(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, findProject.get(result.lastInsertRowid));
    }
    if (request.method === 'PATCH' && projectMatch) {
      const projectId = projectMatch[1];
      if (!findProject.get(projectId)) return json(response, 404, { error: 'Project not found' });
      const input = await readJSON(request);
      if (Object.hasOwn(input || {}, 'default_priority')) {
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(response, 400, { error: 'Default priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, projectId);
        return json(response, 200, findProject.get(projectId));
      }
      if (Object.hasOwn(input || {}, 'name')) {
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectId);
        return json(response, 200, findProject.get(projectId));
      }
      if (typeof input?.archived !== 'boolean') return json(response, 400, { error: 'Archive state must be a boolean' });
      updateProject.run(Number(input.archived), projectId);
      return json(response, 200, findProject.get(projectId));
    }
    const tasksMatch = pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskJSON));
      }
      if (request.method === 'POST' && !taskId) {
        const input = await readJSON(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title, findProject.get(projectId).default_priority);
        return json(response, 201, taskJSON(findTask.get(projectId, result.lastInsertRowid)));
      }
      if (request.method === 'PATCH' && taskId) {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJSON(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        if (Object.hasOwn(input || {}, 'due_date')) {
          const date = normalizeDueDate(input.due_date);
          if (date === null) return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          setDueDate.run(date, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') return json(response, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(response, 200, taskJSON(findTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(pathname) ? '/' : pathname);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Unable to complete request' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
import { filterTasks, normalizeDueRange } from './task-filters.js';

const app = document.getElementById('app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(message) {
  let alert = document.getElementById('error');
  if (!alert) {
    alert = document.createElement('p');
    alert.id = 'error';
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
  alert.hidden = false;
}

function projectRow(project, onArchive) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    document.getElementById('error').hidden = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      onArchive(saved);
    } catch (error) { showError(error.message); }
    finally { archive.disabled = false; }
  });
  row.append(name, summary, open, archive);
  return row;
}

async function renderProject(projectId) {
  const project = await request(`/api/projects/${projectId}`);
  let tasks = await request(`/api/projects/${projectId}/tasks`);
  app.innerHTML = `
    <button type="button" id="back">Projects</button><h1></h1>
    <form id="rename-form">
      <label for="new-project-name">New project name</label>
      <div class="form-controls">
        <input id="new-project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Rename project</button>
      </div>
    </form>
    <div class="project-default">
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority">
        <option value="Low">Low</option>
        <option value="Normal">Normal</option>
        <option value="High">High</option>
      </select>
    </div>
    <form id="task-form">
      <label for="task-title">Task title</label>
      <div class="form-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit">Create task</button>
      </div>
    </form>
    <p id="error" role="alert" hidden></p>
    <h2>Tasks</h2>
    <label for="task-filter">Task filter</label>
    <select id="task-filter">
      <option value="all">All</option>
      <option value="open">Open</option>
      <option value="completed">Completed</option>
    </select>
    <label for="priority-filter">Priority filter</label>
    <select id="priority-filter">
      <option value="all">All</option>
      <option value="Low">Low</option>
      <option value="Normal">Normal</option>
      <option value="High">High</option>
    </select>
    <form id="due-range-form">
      <label for="due-from">Due from</label>
      <input id="due-from" type="text" placeholder="YYYY-MM-DD" autocomplete="off">
      <label for="due-through">Due through</label>
      <input id="due-through" type="text" placeholder="YYYY-MM-DD" autocomplete="off">
      <button type="submit">Apply due range</button>
    </form>
    <p id="empty">No tasks to show.</p>
    <ul id="tasks"></ul>`;
  app.querySelector('h1').textContent = project.name;
  const renameForm = document.getElementById('rename-form');
  const renameInput = document.getElementById('new-project-name');
  renameInput.value = project.name;
  const defaultPriority = document.getElementById('default-task-priority');
  defaultPriority.value = project.default_priority;
  defaultPriority.disabled = Boolean(project.archived);
  defaultPriority.addEventListener('change', async () => {
    defaultPriority.disabled = true;
    document.getElementById('error').hidden = true;
    try {
      const saved = await request(`/api/projects/${projectId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_priority: defaultPriority.value }),
      });
      project.default_priority = saved.default_priority;
    } catch (error) {
      defaultPriority.value = project.default_priority;
      showError(error.message);
    } finally { defaultPriority.disabled = Boolean(project.archived); }
  });
  if (project.archived) {
    const notice = document.createElement('p');
    notice.textContent = 'Archived project';
    app.querySelector('h1').after(notice);
    document.querySelector('#task-form button').disabled = true;
    renameInput.disabled = true;
    renameForm.querySelector('button').disabled = true;
  }
  document.title = `${project.name} · Workboard`;
  renameForm.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    const name = renameInput.value.trim();
    if (!name) { showError('Project name is required'); renameInput.focus(); return; }
    const button = renameForm.querySelector('button');
    button.disabled = true;
    document.getElementById('error').hidden = true;
    try {
      const saved = await request(`/api/projects/${projectId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      project.name = saved.name;
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      renameInput.value = project.name;
    } catch (error) { showError(error.message); }
    finally { button.disabled = false; }
  });
  document.getElementById('back').addEventListener('click', () => location.assign('/'));
  const filter = document.getElementById('task-filter');
  const priorityFilter = document.getElementById('priority-filter');
  const dueFrom = document.getElementById('due-from');
  const dueThrough = document.getElementById('due-through');
  let dueRange = { from: '', through: '' };
  const list = document.getElementById('tasks');
  function drawTasks() {
    const visible = filterTasks(tasks, filter.value, priorityFilter.value, dueRange);
    list.replaceChildren(...visible.map(task => {
      const row = document.createElement('li');
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = Boolean(project.archived);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        document.getElementById('error').hidden = true;
        try {
          const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          tasks = tasks.map(current => current.id === saved.id ? saved : current);
          drawTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error.message);
        } finally { checkbox.disabled = false; }
      });
      const rename = document.createElement('form');
      rename.className = 'task-rename';
      const label = document.createElement('label');
      label.htmlFor = `new-task-title-${task.id}`;
      label.textContent = 'New task title';
      const input = document.createElement('input');
      input.id = label.htmlFor;
      input.type = 'text';
      input.value = task.title;
      input.disabled = Boolean(project.archived);
      const button = document.createElement('button');
      button.type = 'submit';
      button.textContent = 'Rename task';
      button.disabled = Boolean(project.archived);
      const controls = document.createElement('div');
      controls.className = 'form-controls';
      controls.append(input, button);
      rename.append(label, controls);
      rename.addEventListener('submit', async event => {
        event.preventDefault();
        if (project.archived) return;
        const newTitle = input.value.trim();
        if (!newTitle) { showError('Task title is required'); input.focus(); return; }
        button.disabled = true;
        document.getElementById('error').hidden = true;
        try {
          const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: newTitle }),
          });
          tasks = tasks.map(current => current.id === saved.id ? saved : current);
          drawTasks();
        } catch (error) { showError(error.message); }
        finally { button.disabled = Boolean(project.archived); }
      });
      const priorityControl = document.createElement('div');
      const priorityLabel = document.createElement('label');
      priorityLabel.htmlFor = `task-priority-${task.id}`;
      priorityLabel.textContent = 'Task priority';
      const priority = document.createElement('select');
      priority.id = priorityLabel.htmlFor;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        priority.append(option);
      }
      priority.value = task.priority;
      priority.disabled = Boolean(project.archived);
      priority.addEventListener('change', async () => {
        priority.disabled = true;
        document.getElementById('error').hidden = true;
        try {
          const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          });
          tasks = tasks.map(current => current.id === saved.id ? saved : current);
          drawTasks();
        } catch (error) {
          priority.value = task.priority;
          showError(error.message);
        } finally { priority.disabled = Boolean(project.archived); }
      });
      priorityControl.append(priorityLabel, priority);
      const dueDateForm = document.createElement('form');
      dueDateForm.className = 'task-due-date';
      const dueDateLabel = document.createElement('label');
      dueDateLabel.htmlFor = `task-due-date-${task.id}`;
      dueDateLabel.textContent = 'Task due date';
      const dueDateInput = document.createElement('input');
      dueDateInput.id = dueDateLabel.htmlFor;
      dueDateInput.type = 'text';
      dueDateInput.placeholder = 'YYYY-MM-DD';
      dueDateInput.value = task.due_date;
      dueDateInput.disabled = Boolean(project.archived);
      const saveDate = document.createElement('button');
      saveDate.type = 'submit';
      saveDate.textContent = 'Save due date';
      saveDate.disabled = Boolean(project.archived);
      const dateControls = document.createElement('div');
      dateControls.className = 'form-controls';
      dateControls.append(dueDateInput, saveDate);
      dueDateForm.append(dueDateLabel, dateControls);
      dueDateForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (project.archived) return;
        saveDate.disabled = true;
        document.getElementById('error').hidden = true;
        try {
          const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ due_date: dueDateInput.value }),
          });
          tasks = tasks.map(current => current.id === saved.id ? saved : current);
          drawTasks();
        } catch (error) { showError(error.message); }
        finally { saveDate.disabled = Boolean(project.archived); }
      });
      row.append(title, checkbox, priorityControl, rename, dueDateForm);
      return row;
    }));
    document.getElementById('empty').hidden = visible.length > 0;
  }
  filter.addEventListener('change', drawTasks);
  priorityFilter.addEventListener('change', drawTasks);
  document.getElementById('due-range-form').addEventListener('submit', event => {
    event.preventDefault();
    try {
      dueRange = normalizeDueRange(dueFrom.value, dueThrough.value);
      dueFrom.value = dueRange.from;
      dueThrough.value = dueRange.through;
      document.getElementById('error').hidden = true;
      drawTasks();
    } catch (error) { showError(error.message); }
  });
  drawTasks();
  document.getElementById('task-form').addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    const input = document.getElementById('task-title');
    const title = input.value.trim();
    if (!title) { showError('Task title is required'); input.focus(); return; }
    const button = event.currentTarget.querySelector('button');
    button.disabled = true;
    document.getElementById('error').hidden = true;
    try {
      tasks.push(await request(`/api/projects/${projectId}/tasks`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      }));
      drawTasks();
      input.value = '';
      input.focus();
    } catch (error) { showError(error.message); }
    finally { button.disabled = false; }
  });
}

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    await renderProject(match[1]);
    return;
  }
  let projects = await request('/api/projects');
  app.innerHTML = `
    <h1>Workboard</h1>
    <form>
      <label for="project-name">Project name</label>
      <div class="form-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    <p id="error" role="alert" hidden></p>
    <h2>Projects</h2>
    <label for="project-filter">Project filter</label>
    <select id="project-filter">
      <option value="active">Active</option>
      <option value="archived">Archived</option>
    </select>
    <p id="empty">No projects to show.</p>
    <ul id="projects"></ul>`;
  const list = document.getElementById('projects');
  const empty = document.getElementById('empty');
  const filter = document.getElementById('project-filter');
  function drawProjects() {
    const visible = projects.filter(project => Boolean(project.archived) === (filter.value === 'archived'));
    list.replaceChildren(...visible.map(project => projectRow(project, saved => {
      projects = projects.map(current => current.id === saved.id ? saved : current);
      drawProjects();
    })));
    empty.hidden = visible.length > 0;
  }
  filter.addEventListener('change', drawProjects);
  drawProjects();
  app.querySelector('form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const input = document.getElementById('project-name');
    const name = input.value.trim();
    if (!name) { showError('Project name is required'); input.focus(); return; }
    const button = event.currentTarget.querySelector('button');
    button.disabled = true;
    document.getElementById('error').hidden = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
